#pragma once

#include <stdint.h>

/* Tables of the C solver, generated by mytests/rubik/gen_tables.c.
 *
 * rubik_pmove[f * RUBIK_NP + p] and rubik_tmove[f * RUBIK_NT + t]: the
 * permutation rank p and the twist rank t after one clockwise quarter turn of
 * face f (R, B, D). rubik_pdist and rubik_tdist: distance to solved of each
 * coordinate alone, so max(pdist[p], tdist[t]) never overestimates. rubik_ball:
 * every state within 5 moves, sorted, as (p << 10 | t) << 4 | m, where move m
 * brings it one move closer to solved.
 */
#define RUBIK_NP 5040
#define RUBIK_NT 729
#define RUBIK_NBALL 12224

extern const uint16_t rubik_pmove[3 * RUBIK_NP];
extern const uint16_t rubik_tmove[3 * RUBIK_NT];
extern const uint8_t rubik_pdist[RUBIK_NP];
extern const uint8_t rubik_tdist[RUBIK_NT];
extern const uint32_t rubik_ball[RUBIK_NBALL];
